using System;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "Companion Data", menuName = "Data/Battle/Companions/Companion Data")]
public class CompanionData : ScriptableObject
{
	[Header("Data")]
	public string CompanionID;

	public Character Character;

	public CompanionTier CompanionTier;

	[Header("Animation")]
	public AnimationData AnimationData;

	[Header("Units Misc Data")]
	public bool EnableUnitsMiscData;

	[ShowIf("EnableUnitsMiscData")]
	public UnitsMiscData UnitsMiscData;

	[Header("Levels")]
	[HorizontalLine(2f, EColor.Gray)]
	public CompanionLevel[] CompanionLevels = new CompanionLevel[0];

	[Header("Compendium Item State")]
	[SerializeField]
	private CompendiumItemState compendiumItemState;

	[HideInInspector]
	public bool MissingSomething;

	[NonSerialized]
	public string CompanionNameModded = "";

	[NonSerialized]
	public string CompanionDescriptionModded = "";

	[NonSerialized]
	public CompanionLevel[] CompanionLevelsModded = new CompanionLevel[0];

	public bool CantBePickedAsReward;

	public string CompanionName => CompanionID + "_N";

	public string CompanionDescription
	{
		get
		{
			string text = CompanionID;
			if (CompanionID == "MultiphaseGearTwo")
			{
				text = text.Replace("Two", "");
			}
			return text + "_D";
		}
	}

	public CompendiumItemState CompendiumItemState => compendiumItemState;

	public string GetLocalizedCompanionName()
	{
		if (CompanionNameModded != "")
		{
			return CompanionNameModded;
		}
		if (CompanionID == "MultiphaseGear")
		{
			return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(CompanionName) + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("PurifiedPhase");
		}
		if (CompanionID == "MultiphaseGearTwo")
		{
			return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("MultiphaseGear_N") + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("CorruptedPhase");
		}
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(CompanionName);
	}

	public CompanionLevel[] GetCompanionLevels()
	{
		if (IsModdedCompanion())
		{
			return CompanionLevelsModded;
		}
		return CompanionLevels;
	}

	public void SetCompendiumItemState(CompendiumItemState compendiumItemState)
	{
		this.compendiumItemState = compendiumItemState;
	}

	public bool IsModdedCompanion()
	{
		if (ReferenceSingleton<AssetsReference>.Instance.GameController.IsDailyRun)
		{
			return false;
		}
		if (CompanionLevelsModded.Length != 0)
		{
			return true;
		}
		return false;
	}

	public bool IsNewModdedCompanion()
	{
		return CompanionNameModded != "";
	}
}
